window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[39]={"id":"039","numero":39,"titre":"Assistance médicale à la procréation","objectifs":[{"id":"39-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’assistance médicale à la procréation","contenu":"<p>L’<span class=\"kw-def\">assistance médicale à la procréation (AMP)</span> — dénommée aussi <span class=\"kw-def\">procréation médicalement assistée (PMA)</span> — désigne l’ensemble des <strong>pratiques cliniques et biologiques</strong> permettant :</p>\n      <ul>\n        <li>la <strong><span class=\"kw-ttt\">conception in vitro</span></strong> ;</li>\n        <li>la <strong>conservation</strong> des gamètes, des tissus germinaux et des embryons ;</li>\n        <li>le <strong><span class=\"kw-ttt\">transfert d’embryon</span></strong> ;</li>\n        <li>l’<strong>insémination artificielle</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Objectifs légaux (2 motifs alternatifs)</h4>\n      <ul>\n        <li><strong>Remédier à l’infertilité d’un couple</strong> dont le caractère pathologique a été <span class=\"kw-alerte\">médicalement diagnostiqué</span>.</li>\n        <li><strong>Éviter la transmission</strong> d’une <span class=\"kw-def\">maladie d’une particulière gravité</span> à l’enfant ou à un membre du couple.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Périmètre — ce qui n’est PAS de l’AMP</h4>\n      <p>L’<span class=\"kw-clinique\">induction simple de l’ovulation</span> avec des rapports sexuels « programmés » <span class=\"kw-chiffre\">n’est pas stricto sensu</span> une technique d’AMP : elle est encadrée par les règles de bonne pratique médicale mais pas par la loi de bioéthique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Arrêt du projet d’AMP ⭐</h4>\n      <p>Obstacles légaux à l’insémination ou au transfert des embryons :</p>\n      <ul>\n        <li><strong>Décès</strong> d’un des membres du couple.</li>\n        <li><strong>Révocation écrite</strong> du consentement.</li>\n        <li><strong>Demande en divorce</strong>, demande en séparation de corps, ou cessation de la communauté de vie.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pratiques interdites en France ⭐</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Clonage</span> reproductif — <span class=\"kw-ci\">interdit</span> (loi 2004, Code pénal).</li>\n        <li><span class=\"kw-alerte\">Gestation pour autrui (GPA)</span> — <span class=\"kw-ci\">interdite</span> depuis 1994, toute convention nulle, sanction pénale pour entremise.</li>\n        <li><span class=\"kw-alerte\">Insémination post mortem</span> — <span class=\"kw-ci\">interdite</span> (ex : veuve sollicitant le sperme du conjoint décédé).</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Cadre éthique.</strong> L’AMP est l’un des axes structurants des <span class=\"kw-def\">lois de bioéthique</span> (1994, révisions 2004, 2011, 2021). Le <strong><span class=\"kw-def\">CCNE</span></strong> et les <strong><span class=\"kw-def\">ERER</span></strong> accompagnent les révisions. La <span class=\"kw-chiffre\">loi du 2 août 2021</span> est la version en vigueur (cf. obj-11 pour les dispositions réglementaires détaillées).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 9 — Ethique et déontologie médicale</em></p>","frequence":0},{"id":"39-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","contenu":"<p>La <span class=\"kw-def\">préservation de la fertilité</span> désigne le recueil et la conservation de <strong>gamètes</strong> (spermatozoïdes, ovocytes) ou de <strong>tissus germinaux</strong> (cortex ovarien, tissu testiculaire) chez une personne dont la fertilité <strong>risque d’être prématurément altérée</strong>, en vue d’une utilisation ultérieure à son bénéfice — soit pour une AMP autologue, soit pour restaurer la fonction germinale.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Double objectif</h4>\n      <ul>\n        <li><strong>Indication médicale (oncofertilité ++)</strong> — avant un traitement potentiellement stérilisant (<span class=\"kw-ttt\">chimiothérapie</span> gonadotoxique, radiothérapie pelvienne, <span class=\"kw-ttt\">chirurgie</span> mutilante des gonades, maladie de système nécessitant traitement gonadotoxique).</li>\n        <li><strong>Indication non médicale (depuis la loi 2021)</strong> — <span class=\"kw-def\">autoconservation</span> de ses propres gamètes, hors motif médical, prise en charge par l’assurance maladie.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Public concerné — par sexe et par âge</h4>\n      <table >\n        <thead><tr><th>Public</th><th>Préservation possible</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Enfant prépubère</strong></td>\n            <td>\n              <strong>Fille :</strong> <span class=\"kw-ttt\">congélation de cortex ovarien</span> (seule option avant la puberté)<br>\n              <strong>Garçon :</strong> congélation de tissu testiculaire (option en oncofertilité pédiatrique, encore en développement)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Adolescent pubère</strong></td>\n            <td>\n              <strong>Fille :</strong> stimulation ovarienne + <span class=\"kw-ttt\">vitrification ovocytaire</span> ; cortex ovarien si <span class=\"kw-alerte\">urgence</span> ou CI à la stimulation<br>\n              <strong>Garçon :</strong> autoconservation de sperme par masturbation, dès la puberté\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Adulte (oncofertilité)</strong></td>\n            <td>\n              <strong>Femme :</strong> <span class=\"kw-ttt\">vitrification ovocytaire</span>, congélation embryonnaire, cortex ovarien<br>\n              <strong>Homme :</strong> autoconservation de sperme (standard) ; <span class=\"kw-ttt\">ponction</span> épididymaire/testiculaire si azoospermie\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Adulte (hors motif médical, loi 2021)</strong></td>\n            <td>\n              <strong>Femme :</strong> <span class=\"kw-chiffre\">29 à 37 ans</span> révolus<br>\n              <strong>Homme :</strong> <span class=\"kw-chiffre\">29 à 45 ans</span> révolus\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Obligation médicale</h4>\n      <p>Tout médecin doit <strong>proposer</strong> une préservation si la situation médicale l’exige, en particulier avant un traitement gonadotoxique. <span class=\"kw-alerte\">Ne pas le proposer peut constituer un préjudice pour le patient et donc une faute médicale.</span></p>\n\n      <div class=\"callout callout-info\">\n        <strong>Limite.</strong> La préservation de gamètes ou de cortex ovarien n’est <em>pas toujours possible</em> (raisons médicales, refus du patient). Dans ce cas, informer le patient de la possibilité de recourir au <strong>don d’ovocytes</strong> / <strong>don de sperme</strong> ou à l’adoption (cf. obj-8).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux · 38 — Infertilité du couple</em></p>","frequence":0},{"id":"39-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition des différentes techniques d’assistance médicale à la procréation (AMP)","contenu":"<p>L’AMP regroupe plusieurs techniques, hiérarchisées du moins invasif au plus invasif. <strong>Connaître leur définition est rang A.</strong></p>\n\n      <table >\n        <thead>\n          <tr><th>Technique</th><th>Principe</th><th>Spécificités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Insémination artificielle</span></strong> — IAC ou IAD</td>\n            <td>Introduire de façon instrumentale les spz du conjoint (<span class=\"kw-ttt\">IAC</span>) ou d’un donneur (<span class=\"kw-ttt\">IAD</span>) dans le tractus génital féminin (intra-cervical ou intra-utérin).</td>\n            <td>\n              <strong>Quand :</strong> lendemain du pic spontané de LH OU <span class=\"kw-chiffre\">36 h</span> après déclenchement par hCG<br>\n              <strong>Conditions :</strong> trompes perméables + <span class=\"kw-chiffre\">> 1 M</span> spz mobiles + test de migration-survie (TMS) positif\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">FIV classique</span></strong></td>\n            <td>Mise en contact <em>simple</em> in vitro des gamètes durant <span class=\"kw-chiffre\">24 h</span>, hors du tractus génital féminin.</td>\n            <td>Sperme éjaculé en suspension ; la fécondation a lieu spontanément in vitro.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">ICSI</span></strong> (FIV avec micro-injection intracytoplasmique)</td>\n            <td>Injection directe d’<strong>un seul spermatozoïde</strong> par micropipette dans le cytoplasme d’un ovocyte mature en métaphase II.</td>\n            <td>Sperme éjaculé OU ponctionné (<span class=\"kw-ttt\">ponction</span> épididymaire/testiculaire) ; indication principale = infertilité masculine sévère.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">IMSI</span></strong> (variante rare de l’ICSI)</td>\n            <td>ICSI avec spz <em>morphologiquement sélectionné</em> à très fort grossissement.</td>\n            <td>Technique plus rare ; même indication globale que l’ICSI.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">DPI</span></strong> — diagnostic <span class=\"kw-etio\">génétique</span> pré-implantatoire</td>\n            <td>FIV pratiquée par ICSI → embryons prélevés au <span class=\"kw-chiffre\">3ᵉ ou 5ᵉ</span> jour → analyse <span class=\"kw-etio\">génétique</span> (cytogénétique ou moléculaire) → seuls les embryons indemnes sont transférés ou congelés.</td>\n            <td>Réservé aux couples avec <strong>risque de transmission d’une maladie <span class=\"kw-etio\">génétique</span> d’une particulière gravité</strong> (monogénique autosomique ou liée à l’X, récessive ou dominante).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">MIV</span></strong> — maturation in vitro d’ovocytes</td>\n            <td>Prélèvement d’ovocytes sur un ovaire <strong>non stimulé</strong> (ovocytes immatures) → maturation au laboratoire en milieu spécifique.</td>\n            <td>Indiquée si CI à la stimulation ovarienne : <span class=\"kw-alerte\">SOPK</span> (risque HSO), cancer hormonosensible, chimio à instaurer en <span class=\"kw-alerte\">urgence</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Congélation embryonnaire</span></strong> + décongélation + transfert</td>\n            <td>Congélation des embryons surnuméraires de qualité satisfaisante, transfert lors d’un cycle ultérieur (échec, désir d’un autre enfant).</td>\n            <td>L’utilisation de tous les embryons congelés est obligatoire avant toute nouvelle tentative de FIV.</td>\n          </tr>\n          <tr>\n            <td><strong>Don de gamètes</strong> et <strong>don d’embryons</strong></td>\n            <td>Don d’ovocyte, don de sperme, accueil d’embryons congelés surnuméraires.</td>\n            <td>Anonyme et gratuit en France ; pénurie de donneurs ; cf. obj-8.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Double don (depuis 2021).</strong> Le double don (sperme + ovocyte) est désormais autorisé en FIV, justifié si association de :\n        <ul>\n          <li>infertilité masculine OU CI médicale (maladie <span class=\"kw-etio\">génétique</span>) OU absence de partenaire masculin ;</li>\n          <li>insuffisance ovarienne précoce OU CI médicale à l’utilisation des propres ovocytes (maladie <span class=\"kw-etio\">génétique</span>).</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple</em></p>","frequence":1},{"id":"39-4","rang":"A","rubrique":"Définition","titre":"Connaître la définition des différentes techniques de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","contenu":"<p>L’<span class=\"kw-def\">oncofertilité</span> regroupe l’ensemble des techniques de préservation de la fertilité avant un traitement stérilisant (cancer ++). L’autoconservation de sperme chez l’homme est de pratique courante ; les méthodes féminines sont en plein essor.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Côté féminin — 4 techniques</h4>\n      <table >\n        <thead><tr><th>Technique</th><th>Principe</th><th>Indications / particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Transposition ovarienne</span></strong></td>\n            <td>Déplacer chirurgicalement l’ovaire en gouttière pariéto-colique homolatérale pour le sortir du champ d’<span class=\"kw-clinique\">irradiation</span>.</td>\n            <td>Indication : <span class=\"kw-alerte\">radiothérapie pelvienne</span> programmée.</td>\n          </tr>\n          <tr>\n            <td><strong>Prélèvement d’ovocytes matures</strong> (vitrification)</td>\n            <td>Stimulation ovarienne → <span class=\"kw-ttt\">ponction</span> rapide → vitrification d’ovocytes ou d’embryons.</td>\n            <td>Patientes <strong>pubères</strong> uniquement ; nécessite un délai d’environ <span class=\"kw-chiffre\">2 semaines</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Maturation in vitro</span> (MIV)</strong></td>\n            <td><span class=\"kw-ttt\">Ponction</span> d’ovocytes immatures → maturation in vitro au laboratoire → vitrification.</td>\n            <td>Utilisée quand la stimulation est CI : <span class=\"kw-clinique\">cancer hormonosensible</span> (sein, endomètre) OU <span class=\"kw-clinique\">chimiothérapie à instaurer en urgence</span>.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Conservation de tissu ovarien</span></strong> (cortex)</td>\n            <td>Congélation du cortex ovarien (riche en follicules primordiaux) prélevé par <span class=\"kw-clinique\">cœlioscopie opératoire</span>. Objectif = autogreffe ultérieure pour restaurer fertilité + fonction endocrinienne.</td>\n            <td>\n              <strong>Patiente impubère :</strong> seul moyen de préserver la fertilité<br>\n              <strong>Patiente pubère :</strong> en situation d’<span class=\"kw-alerte\">urgence</span>, associée à la MIV\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Côté masculin</h4>\n      <ul>\n        <li><strong><span class=\"kw-ttt\">Autoconservation de sperme par masturbation</span></strong> — technique standard, pratique courante en laboratoire d’AMP en conditions d’asepsie.</li>\n        <li><strong><span class=\"kw-ttt\">Ponction épididymaire ou testiculaire</span></strong> — si <span class=\"kw-clinique\">azoospermie</span>, prélèvement chirurgical de spz à des fins de cryoconservation.</li>\n        <li><strong>Extraction urinaire</strong> — si éjaculation rétrograde.</li>\n        <li><strong><span class=\"kw-ttt\">Congélation de tissu testiculaire</span></strong> — option de recherche/exception chez l’enfant prépubère (avant chimio gonadotoxique).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter (oncofertilité pédiatrique).</strong> La fiche source détaille la préservation féminine en oncofertilité mais reste succincte sur les techniques masculines spécifiques à l’enfant prépubère (statut expérimental du tissu testiculaire). Kevin enrichira ce paragraphe via Collège pédiatrie / référentiels SFOP si besoin.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux · 297 — Cancer de l'enfant</em></p>","frequence":0},{"id":"39-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la fréquence du recours à l’AMP en France","contenu":"<p>Données épidémiologiques principales à retenir pour l’EDN — toutes issues de la fiche source officielle.</p>\n\n      <table >\n        <thead><tr><th>Donnée</th><th>Valeur</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Recours à l’AMP en France</strong></td>\n            <td>Environ <span class=\"kw-chiffre\">10 %</span> des couples y ont recours.</td>\n          </tr>\n          <tr>\n            <td><strong>Ovocytes immatures non utilisables</strong></td>\n            <td><span class=\"kw-chiffre\">15-20 %</span> des ovocytes ponctionnés (absence du 1ᵉʳ globule polaire).</td>\n          </tr>\n          <tr>\n            <td><strong>Taux de <span class=\"kw-ci\">grossesse</span> — IA</strong></td>\n            <td>\n              <strong>IAC :</strong> <span class=\"kw-chiffre\">10-15 %</span> par tentative<br>\n              <strong>IAD :</strong> <span class=\"kw-chiffre\">~17 %</span> par tentative\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Taux de <span class=\"kw-ci\">grossesse</span> — FIV (cycle de transfert frais)</strong></td>\n            <td><span class=\"kw-chiffre\">20-25 %</span> par cycle (jusqu’à <span class=\"kw-chiffre\">20-40 %</span> selon les points clés du collège, variable selon âge, indication, qualité du sperme).</td>\n          </tr>\n          <tr>\n            <td><strong>Hyperstimulation ovarienne grave</strong></td>\n            <td>Environ <span class=\"kw-chiffre\">2 %</span> des cycles stimulés en vue de FIV (cf. obj-12).</td>\n          </tr>\n          <tr>\n            <td><strong>Délai d’attente pour un don de gamètes</strong></td>\n            <td><span class=\"kw-chiffre\">18-24 mois</span> en raison de la pénurie de donneurs.</td>\n          </tr>\n          <tr>\n            <td><strong>Remboursement</strong></td>\n            <td>\n              <span class=\"kw-chiffre\">6</span> tentatives d’insémination artificielle<br>\n              <span class=\"kw-chiffre\">4</span> tentatives de FIV ± ICSI<br>\n              Au-delà = frais du couple ; en cas de naissance, compteur remis à zéro\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple</em></p>","frequence":0},{"id":"39-6","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales étiologies d’infertilité féminine et masculine nécessitant un recours à l’AMP","contenu":"<p>L’infertilité orientant vers une AMP se distribue en <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>rands compartiments — <strong>féminin</strong>, <strong>masculin</strong>, <strong>couple/idiopathique</strong>. Connaître les principales étiologies est rang A pour orienter la technique d’AMP la plus adaptée.</p>\n\n      <table >\n        <thead><tr><th>Compartiment</th><th>Étiologies principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Féminin</strong></td>\n            <td>\n              <strong>Tubaire :</strong> trompes bouchées (sans <span class=\"kw-etio\">hydrosalpinx</span>) ou absentes (post-chirurgical, post-IGH)<br>\n              <strong>Endométriose :</strong> avec ou sans atteinte tubaire associée<br>\n              <strong>Cervical :</strong> absence de glaire OU glaire hostile aux spz<br>\n              <strong>Ovulatoire :</strong> <span class=\"kw-etio\">anovulations</span> (ex. <span class=\"kw-etio\">hypogonadisme hypogonadotrope</span>), <span class=\"kw-etio\">dysovulations</span> (<span class=\"kw-etio\">SOPK ++</span>)<br>\n              <strong>Ovarien :</strong> <span class=\"kw-alerte\">insuffisance ovarienne prématurée (IOP)</span><br>\n              <strong><span class=\"kw-etio\">Génétique</span> :</strong> risque de transmission d’une maladie génétique grave côté femme\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Masculin</strong></td>\n            <td>\n              <strong>Altérations spermatiques modérées</strong> (corrigées par TMS)<br>\n              <strong>OATS sévère</strong> (oligo-asthéno-tératospermie)<br>\n              <strong>Cryptozoospermie sévère</strong><br>\n              <strong>Azoospermie</strong> obstructive OU non obstructive<br>\n              <strong>Infertilités éjaculatoires</strong> (éjaculation rétrograde, anéjaculation)<br>\n              <strong>Troubles sexuels balistiques</strong><br>\n              <strong><span class=\"kw-etio\">Génétique</span> :</strong> risque de transmission d’une maladie génétique grave côté homme\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Couple / idiopathique</strong></td>\n            <td>\n              <strong>Infertilité inexpliquée / idiopathique</strong> — diagnostic d’exclusion après bilan complet du couple<br>\n              <strong>Risque <span class=\"kw-etio\">génétique</span> partagé</strong> — indication potentielle de DPI<br>\n              <strong>Infertilité d’origine mixte</strong> (féminine + masculine concomitantes)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Pour mémoire.</strong> Le caractère pathologique de l’infertilité doit être <span class=\"kw-alerte\">médicalement diagnostiqué</span> pour ouvrir le recours à l’AMP (cf. obj-0 et obj-11). Le bilan d’infertilité — clinique du couple, spermogramme, courbe de température, dosages hormonaux, <span class=\"kw-imagerie\">échographie</span> pelvienne, <span class=\"kw-imagerie\">hystérosalpingographie</span> — est détaillé à l’item 38 ; il précède toujours l’orientation vers une AMP.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 41 — Endométrisose · 35 — Anomalies cycle menstruel - métrorragie · 124 — Ménopause - andropause</em></p>","frequence":0},{"id":"39-7","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales indications des inséminations artificielles","contenu":"<p>L’insémination artificielle se décline en 2 modalités, selon l’origine du sperme : <strong>IAC</strong> (sperme du conjoint) ou <strong>IAD</strong> (sperme de donneur). Les indications sont distinctes — <span class=\"kw-ci\">ne jamais</span> les mélanger en une liste unique.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications de l’IAC (avec spz du conjoint) ⭐</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Infertilité d’origine cervicale</span> — absence de glaire OU glaire cervicale hostile aux spz.</li>\n        <li><span class=\"kw-clinique\">Altérations spermatiques modérées</span> — corrigées par un test de migration-survie (TMS).</li>\n        <li><span class=\"kw-clinique\">Infertilités masculines d’origine éjaculatoire</span>.</li>\n        <li><span class=\"kw-clinique\">Troubles sexuels balistiques</span>.</li>\n        <li><span class=\"kw-clinique\">Infertilité inexpliquée / idiopathique</span>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications de l’IAD (avec spz de donneur)</h4>\n      <ul>\n        <li><strong>Femme seule</strong> (depuis la loi 2021).</li>\n        <li><span class=\"kw-clinique\">Stérilité masculine</span> — <span class=\"kw-etio\">oligospermie extrême</span> OU <span class=\"kw-alerte\">azoospermie après échec de prélèvement chirurgical de spz</span>.</li>\n        <li><span class=\"kw-alerte\">Risque élevé de transmission d’une maladie génétique grave</span> par le conjoint.</li>\n        <li>Après <strong>échec d’ICSI</strong> dans certains cas.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Conditions techniques préalables</h4>\n      <ul>\n        <li><span class=\"kw-chiffre\">Trompes utérines perméables</span> — vérifiées par hystérosonographie lors du bilan d’infertilité.</li>\n        <li><span class=\"kw-chiffre\">> 1 million</span> de spz mobiles récupérés après préparation du sperme.</li>\n        <li><span class=\"kw-chiffre\">Test de migration-survie</span> positif.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Modalités pratiques.</strong> L’insémination est réalisée soit le lendemain d’un pic spontané de LH, soit <span class=\"kw-chiffre\">36 h</span> après le déclenchement artificiel de l’ovulation (hCG). Le dépôt peut être intra-cervical (préparation simplement déposée au col) ou intra-utérin (cathéter franchissant le col — modalité la plus fréquente).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple</em></p>","frequence":0},{"id":"39-8","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales indications de la fécondation in vitro (FIV) avec ou sans microinjection intracytoplasmique (ICSI)","contenu":"<p>La FIV se décline en 2 modalités selon l’origine de la barrière à la fécondation : <strong>FIV classique</strong> (mise en contact spontanée des gamètes in vitro) et <strong>FIV + ICSI</strong> (injection directe d’un seul spz dans l’ovocyte).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications de la FIV classique</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Endométriose</span> — particulièrement avec atteinte tubaire.</li>\n        <li><span class=\"kw-clinique\">Infertilité tubaire</span> — <span class=\"kw-chiffre\">trompes bouchées</span> (sans <span class=\"kw-etio\">hydrosalpinx</span>) OU <span class=\"kw-chiffre\">absentes</span>.</li>\n        <li><span class=\"kw-clinique\">Troubles de l’ovulation</span> après échec des stimulations ovariennes simples et/ou de l’insémination artificielle.</li>\n        <li><span class=\"kw-clinique\">Échecs répétés d’insémination intra-utérine</span>.</li>\n        <li><span class=\"kw-clinique\">Infertilités idiopathiques</span> (« inexpliquées »).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications de la FIV + ICSI ⭐</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Échec de fécondation après FIV classique</span>.</li>\n        <li><strong>Infertilité d’origine masculine</strong> — <span class=\"kw-alerte\">indication principale</span> de l’ICSI :\n          <ul>\n            <li><span class=\"kw-clinique\">OATS sévère</span> (oligo-asthéno-tératospermie) ;</li>\n            <li><span class=\"kw-clinique\">Cryptozoospermie sévère</span> ;</li>\n            <li><span class=\"kw-clinique\">Azoospermie obstructive ou non obstructive</span> — avec recueil positif de spz épididymaires ou testiculaires.</li>\n          </ul>\n        </li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Si recueil négatif après prélèvement chirurgical</strong> dans une azoospermie : on s’oriente alors vers une <strong>insémination artificielle avec sperme de donneur (IAD)</strong> — pas vers une ICSI sans spermatozoïde.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principe technique de l’ICSI</h4>\n      <p>Injection directe par micropipette d’<strong>un seul spermatozoïde</strong> dans le cytoplasme d’un ovocyte mature recueilli (<span class=\"kw-bio\">ovocyte en métaphase II</span>). Le sperme peut être éjaculé OU obtenu par <span class=\"kw-ttt\">ponction</span> épididymaire ou testiculaire.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 41 — Endométrisose</em></p>","frequence":1},{"id":"39-9","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales indications des dons de gamètes et d’embryons","contenu":"<p>Le don de gamètes (sperme, ovocytes) et l’accueil d’embryons relèvent de cadres distincts, avec des indications spécifiques. Tous sont <span class=\"kw-alerte\">gratuits et anonymes</span> en France (loi de bioéthique).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Don de spermatozoïdes (IAD ou FIV avec sperme de donneur)</h4>\n      <ul>\n        <li><strong>Femme seule</strong> (loi 2021).</li>\n        <li><span class=\"kw-clinique\">Stérilité masculine sévère</span> — <span class=\"kw-etio\">oligospermie extrême</span> OU azoospermie après échec de prélèvement chirurgical.</li>\n        <li><span class=\"kw-alerte\">Risque élevé de transmission d’une maladie génétique grave</span> par le conjoint.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Don d’ovocytes</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Insuffisance ovarienne prématurée (IOP)</span>.</li>\n        <li><span class=\"kw-alerte\">Risque de transmission d’une maladie génétique d’une particulière gravité</span> par la femme.</li>\n        <li><span class=\"kw-clinique\">Échecs de FIV ± ICSI intraconjugale</span> — par mauvaise réponse à la stimulation OU qualité ovocytaire/embryonnaire médiocre.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Don d’embryons (accueil d’embryons) ⭐</h4>\n      <p>L’accueil d’embryon consiste à donner des embryons congelés surnuméraires à un couple présentant :</p>\n      <ul>\n        <li><strong>Soit une double stérilité</strong> — masculine ET féminine (ex : <span class=\"kw-clinique\">azoospermie + IOP</span>).</li>\n        <li><strong>Soit une double indication <span class=\"kw-etio\">génétique</span></strong> — maladie génétique transmissible grave chez <em>chaque</em> membre du couple receveur.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Cadre réglementaire commun</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Disposition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Gratuité</strong></td>\n            <td>Don gratuit ⭐ — pas de rémunération, prise en charge des frais occasionnés uniquement.</td>\n          </tr>\n          <tr>\n            <td><strong>Anonymat</strong></td>\n            <td>Couples donneurs et receveurs ne peuvent connaître leurs identités ⭐. Depuis 2021 : les personnes nées de don peuvent accéder à l’<strong>identité du donneur à leur majorité</strong> (sur consentement express du donneur, sans lequel le don n’est plus possible).</td>\n          </tr>\n          <tr>\n            <td><strong>Filiation</strong></td>\n            <td><span class=\"kw-chiffre\">Aucun lien de filiation</span> ne peut être établi entre l’auteur du don et l’enfant issu de la procréation ⭐. Aucune action en responsabilité possible contre le donneur (il n’est pas le responsable légal).</td>\n          </tr>\n          <tr>\n            <td><strong>Conditions du donneur</strong></td>\n            <td>\n              <strong>Homme :</strong> <span class=\"kw-chiffre\">18-45 ans</span> ⭐<br>\n              <strong>Femme :</strong> <span class=\"kw-chiffre\">18-37 ans</span> ⭐<br>\n              Caryotype normal, enquête <span class=\"kw-etio\">génétique</span> sans risque de transmission\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Consentement</strong></td>\n            <td>Écrit, révocable à tout moment jusqu’à l’utilisation des gamètes. Donneur + conjoint si vie en couple ; receveurs consentent devant <strong>notaire</strong> (filiation).</td>\n          </tr>\n          <tr>\n            <td><strong>Lieu</strong></td>\n            <td>Don de gamètes principalement en <span class=\"kw-def\">CECOS</span> (Centre d’Étude et de Conservation des Œufs et du Sperme). Accueil d’embryons : centres autorisés.</td>\n          </tr>\n          <tr>\n            <td><strong>Pratique</strong></td>\n            <td>L’information à l’enfant n’est pas obligatoire — c’est le <strong>choix des parents légaux</strong> ⭐.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 9 — Ethique et déontologie médicale</em></p>","frequence":0},{"id":"39-10","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales indications de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","contenu":"<p>Deux grandes catégories d’indications, à séparer (Règle A — sous-catégories en blocs distincts) :</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications MÉDICALES (oncofertilité ++)</h4>\n      <p>Avant tout traitement potentiellement <strong>gonadotoxique</strong> ou <strong>stérilisant</strong>. La proposition de préservation est une <span class=\"kw-alerte\">obligation médicale</span> — son omission peut constituer une faute.</p>\n      <ul>\n        <li><strong>Cancer + <span class=\"kw-ttt\">chimiothérapie</span> gonadotoxique</strong> — alkylants (<span class=\"kw-ttt\">cyclophosphamide</span>), <span class=\"kw-ttt\">sels de platine</span>, …</li>\n        <li><strong><span class=\"kw-ttt\">Radiothérapie</span> pelvienne</strong> — indication majeure de la transposition ovarienne côté femme.</li>\n        <li><strong><span class=\"kw-ttt\">Chirurgie</span> mutilante des gonades</strong> — castration thérapeutique.</li>\n        <li><strong>Maladies de système</strong> avec traitement gonadotoxique (<span class=\"kw-ttt\">cyclophosphamide</span> dans le <span class=\"kw-def\">lupus</span> sévère, vascularites…).</li>\n        <li><strong>Conditions génétiques</strong> à risque d’insuffisance ovarienne précoce (<span class=\"kw-etio\">syndrome de Turner</span>, mutation FMR1 prémutation).</li>\n      </ul>\n\n      <h5 style=\"margin:10px 0 4px;font-size:13px;color:#374151;\">Spécificités selon l’âge</h5>\n      <ul>\n        <li><strong>Enfant prépubère — fille :</strong> <span class=\"kw-ttt\">congélation de cortex ovarien</span> (seule option).</li>\n        <li><strong>Enfant prépubère — garçon :</strong> congélation de tissu testiculaire (option en développement).</li>\n        <li><strong>Adolescent pubère :</strong> stimulation + <span class=\"kw-ttt\">vitrification ovocytaire</span> (fille), autoconservation sperme (garçon).</li>\n        <li><strong>Adulte :</strong> idem adolescent + possibilité de congélation embryonnaire si couple constitué.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Indications NON MÉDICALES (depuis loi 2021)</h4>\n      <p>L’<span class=\"kw-def\">autoconservation de gamètes hors motif médical</span> est désormais possible, prise en charge par l’assurance maladie, dans les fenêtres d’âge suivantes :</p>\n      <table >\n        <thead><tr><th>Sexe</th><th>Recueil</th><th>Utilisation ultérieure</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Femme</strong></td>\n            <td>Entre <span class=\"kw-chiffre\">29 et 37 ans</span> révolus</td>\n            <td>Jusqu’au <span class=\"kw-chiffre\">45ᵉ anniversaire</span> de la femme qui a vocation à porter l’enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Homme</strong></td>\n            <td>Entre <span class=\"kw-chiffre\">29 et 45 ans</span> révolus</td>\n            <td>Jusqu’au <span class=\"kw-chiffre\">60ᵉ anniversaire</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Lieu et consentement.</strong> Seuls les établissements publics de santé ou privés à but non lucratif habilités peuvent procéder au prélèvement, recueil et conservation. Le consentement est requis annuellement par écrit. Si absence de réponse pendant <span class=\"kw-chiffre\">10 années consécutives</span>, il peut être mis fin à la conservation.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 295 — Prise en charge d'un malade cancéreux · 297 — Cancer de l'enfant</em></p>","frequence":0,"liens":[{"href":"https://www.chru-strasbourg.fr/amp-preservation-de-la-fertilite/","label":"CHRU Strasbourg — AMP & préservation de la fertilité"}]},{"id":"39-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les explorations cliniques, biologiques et radiologiques minimales à réaliser avant le recours à l’AMP","contenu":"<p>Bilan minimal du couple obligatoire avant toute tentative d’AMP. À séparer en 5 axes (clinique / <span class=\"kw-bio\">sérologies</span> / bilan homme / bilan femme / psychosocial + consentement).</p>\n\n      <table >\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>Examen clinique complet des <strong>2 membres</strong> du couple.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">Sérologies</span> infectieuses</strong> (les 2 membres)</td>\n            <td>\n              <strong>Quelles :</strong> <span class=\"kw-bio\">VIH-1 et VIH-2</span>, <span class=\"kw-bio\">VHB</span>, <span class=\"kw-bio\">VHC</span>, <span class=\"kw-bio\">syphilis</span><br>\n              <strong>Quand :</strong> dans les <span class=\"kw-chiffre\">3 mois</span> précédant la 1ʳᵉ tentative d’AMP<br>\n              <strong>À répéter :</strong> chaque fois que le délai depuis le dernier examen dépasse <span class=\"kw-chiffre\">12 mois</span><br>\n              <strong>Si sérodiscordance</strong> (positif chez 1 des 2 partenaires) : <span class=\"kw-alerte\">PEC pluridisciplinaire en centre spécialisé</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bilan masculin</strong></td>\n            <td>\n              <span class=\"kw-bio\">Spermogramme + spermoculture</span> réalisés <span class=\"kw-chiffre\">&lt; 1 an</span> avant la tentative<br>\n              <span class=\"kw-bio\">Test de migration-survie (TMS)</span> : indiqué dès qu’une AMP est envisagée, sélectionne les spz les plus mobiles, induit la <em>capacitation</em>, résultat exprimé en nombre estimé de spz à mobilité progressive utilisables\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bilan féminin</strong></td>\n            <td>\n              <span class=\"kw-bio\">Prélèvement vaginal</span> récent (&lt; <span class=\"kw-chiffre\">6 mois</span>) — germes banaux, <em>Chlamydiae</em>, mycoplasmes<br>\n              <span class=\"kw-bio\">Vérification de la vaccination rubéole</span><br>\n              <span class=\"kw-bio\">Vérification de la sérologie toxoplasmose</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Psychosocial + consentement</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Consultation obligatoire</span> auprès d’un psychiatre ou psychologue — pour éliminer toute CI psychosociale<br>\n              L’AMP peut ne pas être proposée en 1ʳᵉ intention si le couple semble incapable d’assumer cet investissement (temps, disponibilité, observance)<br>\n              <strong>Consentement écrit</strong> obligatoire à chaque tentative — précisant la technique envisagée (FIV ou ICSI) et l’accord du couple pour la <strong>congélation d’éventuels embryons surnuméraires</strong><br>\n              Si recours à un don de gamètes ou à l’accueil d’embryons → consentement particulier signé devant le <strong>tribunal judiciaire</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Test de migration-survie (TMS).</strong> Complémentaire au spermogramme, indiqué dès qu’une AMP est envisagée. Il reproduit les conditions de préparation du sperme avant toute AMP — sélection des spz les plus mobiles + induction de la capacitation (préalable indispensable à toute fécondation). Le résultat aide à choisir la technique d’AMP la plus appropriée (IAC <span class=\"kw-bio\">vs</span> ICSI selon le nombre de spz mobiles utilisables).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple</em></p>","frequence":1},{"id":"39-12","rang":"B","rubrique":"Prise en charge","titre":"Connaître les dispositions règlementaires encadrant le recours à l’AMP et la préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","contenu":"<p>Cadre légal — <strong>loi de bioéthique du 2 août 2021</strong> (révision des lois de 1994, 2004, 2011). Connaissance des conditions d’accès, du remboursement et des pratiques interdites.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Bénéficiaires (loi 2021)</h4>\n      <ul>\n        <li>Couple d’<strong>un homme et une femme</strong>.</li>\n        <li>Couple de <strong>deux femmes</strong>.</li>\n        <li>Toute <strong>femme non mariée</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Conditions d’âge</h4>\n      <table >\n        <thead><tr><th>Étape</th><th>Femme</th><th>Autre membre du couple</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Prélèvement de gamètes</strong> en vue d’AMP (FIV / ICSI)</td>\n            <td>Jusqu’au <span class=\"kw-chiffre\">43ᵉ</span> anniversaire</td>\n            <td>Jusqu’au <span class=\"kw-chiffre\">60ᵉ</span> anniversaire</td>\n          </tr>\n          <tr>\n            <td><strong>IIU, utilisation de gamètes / tissus germinaux, <span class=\"kw-ttt\">transfert d’embryon</span></strong></td>\n            <td>Jusqu’au <span class=\"kw-chiffre\">45ᵉ</span> anniversaire (femme qui porte l’enfant)</td>\n            <td>Jusqu’au <span class=\"kw-chiffre\">60ᵉ</span> anniversaire</td>\n          </tr>\n          <tr>\n            <td><strong>Autoconservation hors motif médical</strong></td>\n            <td><span class=\"kw-chiffre\">29-37 ans</span></td>\n            <td><span class=\"kw-chiffre\">29-45 ans</span> (homme)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Consentement</h4>\n      <ul>\n        <li><strong>Préalable</strong> au transfert ou à l’insémination — par écrit.</li>\n        <li>Par les <strong>2 membres</strong> du couple ou par la femme non mariée.</li>\n        <li>Si recours au don de gamètes ou à l’accueil d’embryons → consentement particulier devant <strong>tribunal judiciaire</strong>.</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Remboursement par l’assurance maladie</h4>\n      <table >\n        <thead><tr><th>Item</th><th>Disposition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Taux de PEC</strong></td>\n            <td>Infertilité prise en charge à <span class=\"kw-chiffre\">100 %</span> (exploration médicale + traitements prescrits).</td>\n          </tr>\n          <tr>\n            <td><strong>Nombre de tentatives remboursées</strong></td>\n            <td>\n              <span class=\"kw-chiffre\">6</span> tentatives d’<strong>insémination artificielle</strong><br>\n              <span class=\"kw-chiffre\">4</span> tentatives de <strong>FIV ± ICSI</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>En cas d’échec</strong></td>\n            <td>Au-delà du quota et sans naissance, la PEC est aux <span class=\"kw-alerte\">frais du couple</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>En cas de réussite (naissance)</strong></td>\n            <td>Le compteur est <strong>remis à zéro</strong>.</td>\n          </tr>\n          <tr>\n            <td><strong>Embryons congelés</strong></td>\n            <td>Obligation d’utiliser tous les embryons congelés avant toute nouvelle tentative de FIV.</td>\n          </tr>\n          <tr>\n            <td><strong>Consultation annuelle</strong></td>\n            <td>Couple ou femme non mariée consultés tous les ans pour confirmer le maintien du projet parental. Si séparation ou abandon → demande de destruction, cession à la recherche, ou cession à un autre couple.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Pratiques interdites ⭐</h4>\n      <table >\n        <thead><tr><th>Pratique</th><th>Fondement légal</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-alerte\">Clonage reproductif</span></td>\n            <td>Loi 2004 : « Nul ne peut porter atteinte à l’intégrité de l’espèce humaine. » Toute pratique eugénique tendant à organiser la sélection des personnes est <span class=\"kw-ci\">interdite</span>. Sanctions pénales.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Gestation pour autrui (GPA)</span></td>\n            <td>Interdite depuis 1994, confirmée par la loi 2021. Toute convention portant sur la procréation ou la gestation pour autrui est <strong>nulle</strong>. Le Code pénal sanctionne l’entremise (emprisonnement + amende). En 2021, le Code civil a précisé que la reconnaissance d’une filiation à l’étranger est appréciée au regard de la loi française — transcription de l’acte limitée au seul parent <span class=\"kw-ttt\">biologique</span> ; le second parent dit « d’intention » doit passer par une procédure d’<strong>adoption</strong>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\">Insémination post mortem</span></td>\n            <td>Interdite — exemple type : veuve sollicitant le sperme du conjoint décédé.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Cadre éthique.</strong> Les lois de bioéthique sont révisées à échéances régulières. Le <strong><span class=\"kw-def\">CCNE</span></strong> (Conseil consultatif national d’éthique) et les <strong><span class=\"kw-def\">ERER</span></strong> (espaces de réflexion éthique régionaux) accompagnent les révisions. L’avis 129 du <span class=\"kw-def\">CCNE</span> (septembre 2018), issu des États généraux de la bioéthique, a précédé la loi 2021.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 9 — Ethique et déontologie médicale · 8 — Discriminations</em></p>","frequence":0},{"id":"39-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principales complications des techniques d’AMP et de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","contenu":"<p>Les complications de l’AMP sont à connaître par étape technique. La complication majeure à reconnaître est le <span class=\"kw-alerte\">syndrome d’hyperstimulation ovarienne (HSO)</span>.</p>\n\n      <table >\n        <thead><tr><th>Étape</th><th>Complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Stimulation ovarienne — effets secondaires</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Asthénie</span>, <span class=\"kw-clinique\">céphalées</span>, troubles digestifs, <span class=\"kw-clinique\">pertes de mémoire</span><br>\n              <span class=\"kw-clinique\">Métrorragies</span>, mastodynies, bouffées de chaleur, <span class=\"kw-clinique\">prise de poids</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Stimulation ovarienne — complications</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Allergie</span> aux produits utilisés<br>\n              <span class=\"kw-alerte\">Accidents thrombotiques</span> — souvent à l’occasion d’une HSO<br>\n              <span class=\"kw-alerte\">Torsion d’annexe</span> — sur ovaire stimulé avec de multiples follicules de grande taille<br>\n              <span class=\"kw-alerte\">Syndrome d’hyperstimulation ovarienne (HSO)</span> — voir encadré ci-dessous\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ttt\">Ponction</span> ovocytaire</strong></td>\n            <td>\n              Complications de l’<span class=\"kw-clinique\">anesthésie</span><br>\n              Complications <span class=\"kw-clinique\">infectieuses</span> — <span class=\"kw-clinique\">abcès</span> ovarien ou pelvien<br>\n              Complications <span class=\"kw-clinique\">hémorragiques</span> — hémopéritoine, plaie digestive ou vasculaire\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Grossesses issues d’AMP</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Grossesse multiple</span> et ses complications<br>\n              <span class=\"kw-clinique\">Pathologies vasculaires gravidiques</span> (<span class=\"kw-etio\">HTA</span>, pré-éclampsie) plus fréquentes<br>\n              <span class=\"kw-clinique\">Diabète gestationnel</span> plus fréquent — populations souvent plus âgées\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\" style=\"background:#f3dccf;border-left:4px solid var(--danger);\">\n        <strong>Syndrome d’hyperstimulation ovarienne (HSO) ⭐</strong>\n        <ul>\n          <li><strong>Fréquence :</strong> HSO grave dans environ <span class=\"kw-chiffre\">2 %</span> des cycles stimulés en vue de FIV.</li>\n          <li><strong>Gravité variable</strong> — peut mettre en jeu le <span class=\"kw-alerte\">pronostic vital maternel</span>.</li>\n          <li><strong>Formes sévères :</strong>\n            <ul>\n              <li><span class=\"kw-alerte\">Insuffisance rénale aiguë</span></li>\n              <li><span class=\"kw-alerte\">Ascite majeure</span>, pleurésie, <span class=\"kw-alerte\">SDRA</span></li>\n              <li><span class=\"kw-alerte\">Accidents thromboemboliques</span></li>\n              <li>Leucocytose importante</li>\n            </ul>\n          </li>\n          <li><strong><span class=\"kw-def\">Facteurs de risque</span> :</strong> SOPK, âge jeune, IMC bas, AMH élevée — d’où l’indication de la MIV chez les SOPK.</li>\n        </ul>\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Complications spécifiques à la préservation de fertilité</h4>\n      <ul>\n        <li><strong>Oncofertilité — risque de retard</strong> de mise en route du traitement carcinologique si stimulation ovarienne préalable (à mettre en balance avec la fertilité ultérieure).</li>\n        <li><strong>Congélation de cortex ovarien</strong> — complications de la <span class=\"kw-clinique\">cœlioscopie opératoire</span> (anesthésie, plaies viscérales, hémorragie, infection).</li>\n        <li><strong>Autoconservation de sperme</strong> — pas de complication somatique notable ; impact psychologique à considérer.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> La fiche source décrit en détail les complications des techniques de FIV mais reste succincte sur les complications psychiques et le retentissement à long terme de la préservation de fertilité (impact sur la décision thérapeutique en oncofertilité pédiatrique, vécu du couple en cas d’échec). Kevin enrichira via Collège gynéco / référentiel SFOP si besoin.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 38 — Infertilité du couple · 23 — <span class=\"kw-ci\">Grossesse</span> normale</em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Syndrome d'hyperstimulation ovarienne grave <span class=\"q\">— <span class=\"kw-alerte\">pronostic vital engagé</span></span></strong></p><p><span class=\"kw-alerte\">Hospitalisation</span> + correction hydroélectrolytique + <span class=\"kw-ttt\">anticoagulation préventive</span> ; surseoir au transfert embryonnaire</p><ul><li><span class=\"kw-alerte\">Insuffisance rénale aiguë</span> + <span class=\"kw-alerte\">ascite majeure</span> + <span class=\"kw-alerte\">SDRA</span> + <span class=\"kw-alerte\">accidents thromboemboliques</span> : formes sévères</li><li>Survient dans environ <span class=\"kw-chiffre\">2 %</span> des cycles stimulés en vue de <span class=\"kw-def\">FIV</span></li><li><span class=\"kw-etio\">Terrain à risque</span> : <span class=\"kw-def\">SOPK</span>, réponse ovarienne excessive à la stimulation</li></ul><p><strong>Torsion d'annexe sur ovaire stimulé</strong></p><p><span class=\"kw-ttt\">Cœlioscopie</span> de détorsion en <span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">&lt; 6 h</span>)</p><ul><li>Ovaire augmenté de volume (multiples follicules), hypermobile → risque de <span class=\"kw-alerte\">nécrose ovarienne</span></li><li><span class=\"kw-clinique\">Douleur pelvienne brutale</span>, <span class=\"kw-clinique\">nausées-vomissements</span>, <span class=\"kw-imagerie\">absence de vascularisation Doppler</span></li></ul><p><strong>Oncofertilité — <span class=\"kw-ttt\">chimiothérapie</span> urgente</strong></p><p><span class=\"kw-ttt\">Maturation in vitro (MIV)</span> d'ovocytes non stimulés + vitrification ovocytaire immédiate</p><ul><li>Cancer dont le traitement doit être instauré <strong>sans délai</strong> : stimulation ovarienne (<span class=\"kw-chiffre\">≈ 2 semaines</span>) impossible</li><li><span class=\"kw-ci\">Contre-indication à la stimulation</span> si cancer hormonosensible (<span class=\"kw-etio\">sein</span>, <span class=\"kw-etio\">endomètre</span>)</li></ul>","hospit":"<p><strong>Sérodiscordance :</strong> si <span class=\"kw-bio\">sérologie</span> <span class=\"kw-bio\">VIH / VHB / VHC / syphilis</span> positive chez l'un des partenaires → <span class=\"kw-ttt\">PEC pluridisciplinaire en centre spécialisé</span>.<br><strong>DPI :</strong> indications validées systématiquement par un <span class=\"kw-def\">CPDPN</span> (Centre Pluridisciplinaire de Diagnostic Prénatal).<br><strong>Don de gamètes :</strong> réalisé principalement en <span class=\"kw-def\">CECOS</span> (Centre d'Étude et de Conservation des Œufs et du Sperme).<br><strong>Autoconservation :</strong> uniquement dans un établissement public ou ESPIC <strong>habilité</strong> (faute médicale si non proposé avant traitement stérilisant).</p>","redflags":"<ul><li><span class=\"kw-alerte\">SHO sévère</span> : ascite massive, oligurie/anurie, <span class=\"kw-clinique\">dyspnée</span>, <span class=\"kw-alerte\">état de choc</span></li><li><span class=\"kw-alerte\">Torsion d'annexe</span> : douleur pelvienne brutale sur ovaire stimulé → <span class=\"kw-alerte\">urgence</span> chirurgicale</li><li><span class=\"kw-alerte\">Abcès ovarien ou pelvien</span> après <span class=\"kw-ttt\">ponction</span> folliculaire</li><li><span class=\"kw-alerte\">Hémopéritoine</span> post-<span class=\"kw-ttt\">ponction</span> : plaie vasculaire ou digestive</li><li><span class=\"kw-alerte\">Accident thromboembolique</span> : <span class=\"kw-def\">MTEV</span> dans un contexte de SHO</li></ul>","principes":"<p><strong>Bilan pré-AMP réglementé :</strong> <span class=\"kw-bio\">sérologies</span> (<span class=\"kw-bio\">VIH 1&amp;2, VHB, VHC, syphilis</span>) <span class=\"kw-chiffre\">dans les 3 mois</span> précédant la 1ʳᵉ tentative ; spermogramme <span class=\"kw-chiffre\">&lt; 1 an</span> ; prélèvement vaginal <span class=\"kw-chiffre\">&lt; 6 mois</span>.</p><p><strong>Nombre de tentatives remboursées</strong></p><ul><li><span class=\"kw-chiffre\">6</span> tentatives d'<span class=\"kw-def\">insémination artificielle</span> (IA) remboursées à <span class=\"kw-chiffre\">100 %</span></li><li><span class=\"kw-chiffre\">4</span> tentatives de <span class=\"kw-def\">FIV</span> ou <span class=\"kw-def\">ICSI</span> remboursées à <span class=\"kw-chiffre\">100 %</span></li><li>En cas de réussite (naissance) : compteur <strong>remis à zéro</strong></li><li><span class=\"kw-ci\">Au-delà : frais à la charge du couple</span></li></ul><p><strong>CI à la stimulation → recours à la MIV</strong></p><ul><li><span class=\"kw-def\">SOPK</span> : risque de <span class=\"kw-alerte\">SHO</span> → <span class=\"kw-ttt\">MIV</span> de préférence</li><li>Cancer <span class=\"kw-etio\">hormonosensible</span> (<span class=\"kw-etio\">sein</span>, <span class=\"kw-etio\">endomètre</span>) : <span class=\"kw-ci\">FSH contre-indiquée</span> → <span class=\"kw-ttt\">MIV</span></li><li>Traitement oncologique urgent : pas de délai pour stimulation → <span class=\"kw-ttt\">MIV</span> immédiate</li></ul><p><strong>Arrêt du projet AMP</strong></p><ul><li>Décès d'un des membres du couple</li><li>Révocation par écrit du consentement</li><li>Demande en divorce / séparation / cessation de la communauté de vie</li></ul>","suivi":"<p><strong>Monitoring folliculaire :</strong> <span class=\"kw-imagerie\">échographie</span> (compte + mesure follicules) + dosages hormonaux (<span class=\"kw-bio\">œstradiol, progestérone, LH</span>) à chaque cycle stimulé.<br><strong>Test de <span class=\"kw-ci\">grossesse</span> :</strong> systématique à <span class=\"kw-chiffre\">J14</span> après <span class=\"kw-ttt\">ponction</span> (<span class=\"kw-chiffre\">J12</span> après transfert) ; si positif, <span class=\"kw-imagerie\">échographie de localisation</span>.<br><strong>Embryons congelés :</strong> consultation annuelle écrite des membres du couple pour maintien du projet parental ; conservation arrêtée si absence de réponse pendant <span class=\"kw-chiffre\">10 années consécutives</span>.</p>"},"liensGlobaux":[{"href":"https://www.chru-strasbourg.fr/amp-preservation-de-la-fertilite","label":"chru-strasbourg.fr"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Couple en bilan d'AMP — Après bilan complet : spermogramme + test migration-survie + hystérosonographie + bilan féminin","detail":"<h4>Choix de la technique d'AMP — Orientation selon perméabilité tubaire, qualité spermatique et <span class=\"kw-ci\">contre-indications</span> à la stimulation</h4>","branches":[{"to":"q-indication-ia","label":"Trompes perméables + spermatozoïdes mobiles > 1 million après préparation","color":"green"},{"to":"q-recueil-spz","label":"Altérations spermatiques sévères (OATS sévère, cryptozoospermie, azoospermie)","color":"amber"}]},{"id":"q-indication-ia","kind":"decision","label":"Indication spécifique à l'IA ? — Infertilité cervicale, altérations spermatiques modérées, troubles éjaculatoires, infertilité idiopathique","branches":[{"to":"t-iac","label":"Oui — indication d'IA avec sperme conjoint","color":"green"},{"to":"q-ci-stimulation","label":"Non — indication de FIV (trompes bouchées, échecs IA, endométriose…)","color":"amber"}]},{"id":"t-iac","kind":"terminal","label":"IAC — Insémination Artificielle avec sperme du Conjoint","color":"green","detail":"<h4>Indications</h4><ul><li><span class=\"kw-etio\">Infertilité cervicale</span> (absence ou hostilité de la glaire)</li><li><span class=\"kw-etio\">Altérations spermatiques modérées</span> (test migration-survie positif)</li><li><span class=\"kw-etio\">Infertilité masculine d'origine éjaculatoire</span></li><li><span class=\"kw-etio\">Troubles sexuels balistiques</span></li><li><span class=\"kw-etio\">Infertilité inexpliquée/idiopathique</span></li></ul><h4>Conditions</h4><ul><li>Trompes perméables + <span class=\"kw-chiffre\">&gt; 1 million</span> spz mobiles après préparation</li></ul><h4>Résultats</h4><ul><li><span class=\"kw-chiffre\">10–15 %</span> de <span class=\"kw-ci\">grossesse</span> par tentative avec sperme conjoint</li></ul><h4>Remboursement</h4><ul><li><span class=\"kw-chiffre\">6 tentatives</span> remboursées à <span class=\"kw-chiffre\">100 %</span></li></ul>"},{"id":"q-ci-stimulation","kind":"decision","label":"Contre-indication à la stimulation ovarienne ? — SOPK à risque de SHO, cancer hormonosensible, traitement oncologique urgent","branches":[{"to":"t-fiv","label":"Non — stimulation possible","color":"green"},{"to":"t-miv","label":"Oui — CI à la stimulation (SOPK / cancer hormonosensible / urgence chimio)","color":"amber"}]},{"id":"t-fiv","kind":"terminal","label":"FIV classique","color":"green","detail":"<h4>Indications</h4><ul><li><span class=\"kw-etio\">Infertilité tubaire</span> (trompes bouchées ou absentes)</li><li><span class=\"kw-etio\">Endométriose</span></li><li><span class=\"kw-etio\">Troubles de l'ovulation</span> après échecs de stimulation simple et/ou IA</li><li><span class=\"kw-etio\">Infertilité idiopathique</span> après échecs d'IA</li></ul><h4>Principe</h4><ul><li>Mise en contact simple des gamètes in vitro pendant <span class=\"kw-chiffre\">24 h</span> ; <span class=\"kw-ttt\">stimulation ovarienne</span> + <span class=\"kw-ttt\">ponction folliculaire</span> sous <span class=\"kw-imagerie\">échoguidage</span></li></ul><h4>Remboursement</h4><ul><li><span class=\"kw-chiffre\">4 tentatives</span> remboursées à <span class=\"kw-chiffre\">100 %</span></li></ul>"},{"id":"t-miv","kind":"terminal","label":"MIV — Maturation In Vitro","color":"amber","detail":"<h4>Indications</h4><ul><li><span class=\"kw-def\">SOPK</span> : <span class=\"kw-ci\">contre-indication</span> à la stimulation (<span class=\"kw-alerte\">risque de SHO</span>)</li><li>Cancer <span class=\"kw-etio\">hormonosensible</span> (<span class=\"kw-etio\">sein</span>, <span class=\"kw-etio\">endomètre</span>) : <span class=\"kw-ci\">FSH contre-indiquée</span></li><li>Traitement oncologique devant être instauré <strong>rapidement</strong> (pas de délai possible)</li></ul><h4>Principe</h4><ul><li><span class=\"kw-ttt\">Ponction</span> d'ovocytes <strong>sans stimulation préalable</strong> → <span class=\"kw-ttt\">maturation au laboratoire</span> → vitrification</li></ul><h4>Particularité oncofertilité</h4><ul><li>Associée à la <span class=\"kw-ttt\">conservation de tissu ovarien</span> dans les situations d'<span class=\"kw-alerte\">urgence</span></li></ul>"},{"id":"q-recueil-spz","kind":"decision","label":"Recueil de spermatozoïdes possible ? — Ponction épididymaire (PESA) ou testiculaire (TESE) si azoospermie","branches":[{"to":"t-icsi","label":"Oui — spermatozoïdes récupérés (éjaculé ou ponction)","color":"green"},{"to":"t-iad","label":"Non — recueil négatif ou risque génétique transmissible grave","color":"blue"}]},{"id":"t-icsi","kind":"terminal","label":"ICSI — Injection Intracytoplasmique","color":"green","detail":"<h4>Indications</h4><ul><li><span class=\"kw-def\">OATS sévère</span> (oligo-asthéno-tératospermie)</li><li><span class=\"kw-def\">Cryptozoospermie sévère</span></li><li><span class=\"kw-def\">Azoospermie obstructive ou non obstructive</span> avec recueil positif</li><li>Échec de fécondation après FIV classique</li></ul><h4>Principe</h4><ul><li>Injection directe d'<span class=\"kw-chiffre\">1 seul spermatozoïde</span> dans le cytoplasme de l'ovocyte mature (métaphase II)</li></ul><h4>Remboursement</h4><ul><li><span class=\"kw-chiffre\">4 tentatives</span> remboursées à <span class=\"kw-chiffre\">100 %</span></li></ul>"},{"id":"t-iad","kind":"terminal","label":"IAD — Insémination Artificielle avec sperme de Donneur","color":"blue","detail":"<h4>Indications</h4><ul><li><span class=\"kw-etio\">Azoospermie</span> après échec de prélèvement chirurgical de spz</li><li><span class=\"kw-etio\">Oligospermie extrême</span> sans recueil utilisable</li><li>Risque élevé de <span class=\"kw-etio\">transmission d'une maladie génétique grave</span> par le conjoint</li><li>Femme seule</li><li>Après échec d'ICSI dans certains cas</li></ul><h4>Règles don</h4><ul><li><span class=\"kw-ttt\">Don gratuit et anonyme</span> ; réalisé en <span class=\"kw-def\">CECOS</span> ; délai d'attente <span class=\"kw-chiffre\">18–24 mois</span> (pénurie de donneurs)</li></ul><h4>Résultats</h4><ul><li><span class=\"kw-chiffre\">17 %</span> de <span class=\"kw-ci\">grossesse</span> par tentative avec sperme de donneur</li></ul>"}]},"cards":[{"i":"2f87af98557a","n":39,"o":"39-1","u":"Définition","t":"Connaître la définition de l’assistance médicale à la procréation","q":"Quels obstacles légaux peuvent entraîner l'arrêt d'un projet d'AMP, notamment l'insémination ou le transfert d'embryons ?","a":"<p>Les obstacles légaux à l'insémination ou au transfert d'embryons incluent :</p><ul><li>Le <strong>décès d'un des membres du couple</strong>.</li><li>Une <strong>révocation écrite du consentement</strong>.</li><li>Une demande en divorce, une demande en séparation de corps, ou la <strong>cessation de la communauté de vie</strong>.</li></ul>"},{"i":"70aeb7deaf43","n":39,"o":"39-1","u":"Définition","t":"Connaître la définition de l’assistance médicale à la procréation","q":"Quelle est la définition de l'Assistance Médicale à la Procréation (AMP) et quelles pratiques regroupe-t-elle ?","a":"<p>L'Assistance Médicale à la Procréation (AMP), aussi appelée Procréation Médicalement Assistée (PMA), représente l'ensemble des pratiques cliniques et biologiques permettant :</p><ul><li>La <strong>conception in vitro</strong>.</li><li>La <strong>conservation des gamètes, des tissus germinaux et des embryons</strong>.</li><li>Le <strong>transfert d'embryon</strong>.</li><li>L'<strong>insémination artificielle</strong>.</li></ul>"},{"i":"a8c7b230803b","n":39,"o":"39-1","u":"Définition","t":"Connaître la définition de l’assistance médicale à la procréation","q":"Quels sont les objectifs légaux de l'Assistance Médicale à la Procréation (AMP) en France ?","a":"<p>L'AMP vise deux objectifs légaux alternatifs :</p><ul><li>Remédier à l'<strong>infertilité d'un couple</strong> dont le caractère pathologique a été médicalement diagnostiqué.</li><li>Éviter la <strong>transmission d'une maladie d'une particulière gravité</strong> à l'enfant ou à un membre du couple.</li></ul>"},{"i":"ccca3ec33dfc","n":39,"o":"39-1","u":"Définition","t":"Connaître la définition de l’assistance médicale à la procréation","q":"Quelles pratiques de procréation ne sont pas considérées comme de l'Assistance Médicale à la Procréation (AMP) au sens strict en France ?","a":"<p>L'<strong>induction simple de l'ovulation</strong> avec des rapports sexuels « programmés » n'est pas considérée comme une technique d'AMP au sens strict. Elle est encadrée par les règles de bonne pratique médicale, mais pas par la loi de bioéthique.</p>"},{"i":"e0a166c07639","n":39,"o":"39-1","u":"Définition","t":"Connaître la définition de l’assistance médicale à la procréation","q":"Quelles sont les pratiques de procréation strictement interdites en France dans le cadre de l'AMP ?","a":"<p>Les pratiques interdites en France sont :</p><ul><li>Le <strong>clonage reproductif</strong> (interdit depuis <strong>2004</strong>).</li><li>La <strong>gestation pour autrui (GPA)</strong> (interdite depuis <strong>1994</strong>).</li><li>L'<strong>insémination post-mortem</strong>.</li></ul>"},{"i":"630fd807371b","n":39,"o":"39-10","u":"Etiologies","t":"Connaître les principales indications de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelles sont les spécificités de la préservation de la fertilité selon l'âge pour les indications médicales ?","a":"<ul><li>Chez l'<strong>enfant prépubère</strong> fille : la seule option est la <strong>congélation de cortex ovarien</strong>.</li><li>Chez l'<strong>enfant prépubère</strong> garçon : la congélation de tissu testiculaire est une option en développement.</li><li>Chez l'<strong>adolescent pubère</strong> fille : la <strong>stimulation et vitrification ovocytaire</strong>.</li><li>Chez l'<strong>adolescent pubère</strong> garçon : l'<strong>autoconservation de sperme</strong>.</li><li>Chez l'<strong>adulte</strong> : les mêmes options que l'adolescent, avec en plus la possibilité de <strong>congélation embryonnaire</strong> si le couple est constitué.</li></ul>"},{"i":"942966a33d9c","n":39,"o":"39-10","u":"Etiologies","t":"Connaître les principales indications de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelles sont les indications non médicales de préservation de la fertilité et les conditions associées selon la loi de 2021 ?","a":"<p>Depuis la loi de 2021, l'<strong>autoconservation de gamètes hors motif médical</strong> est possible et prise en charge par l'assurance maladie, sous certaines conditions :</p><ul><li>Pour les <strong>femmes</strong> : le recueil est possible entre <strong>29 et 37 ans révolus</strong>, et l'utilisation est possible jusqu'au <strong>45<sup>e</sup> anniversaire</strong> de la femme porteuse de l'enfant.</li><li>Pour les <strong>hommes</strong> : le recueil est possible entre <strong>29 et 45 ans révolus</strong>, et l'utilisation est possible jusqu'au <strong>60<sup>e</sup> anniversaire</strong>.</li><li>Seuls les établissements publics de santé ou privés à but non lucratif habilités peuvent réaliser le prélèvement, recueil et conservation.</li><li>Le <strong>consentement annuel écrit</strong> est requis, et l'absence de réponse pendant 10 années consécutives peut entraîner l'arrêt de la conservation.</li></ul>"},{"i":"b38142640dc4","n":39,"o":"39-10","u":"Etiologies","t":"Connaître les principales indications de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelles sont les principales indications médicales de préservation de la fertilité féminine et masculine ?","a":"<p>Les principales indications médicales de préservation de la fertilité sont :</p><ul><li>Les traitements potentiellement gonadotoxiques ou stérilisants, notamment les <strong>cancers</strong> (chimiothérapie gonadotoxique comme les <strong>alkylants</strong>, sels de platine, radiothérapie pelvienne).</li><li>La <strong>chirurgie mutilante des gonades</strong>.</li><li>Les <strong>maladies de système</strong> nécessitant un traitement gonadotoxique (ex: <strong>cyclophosphamide</strong> dans le lupus sévère, vascularites).</li><li>Les <strong>conditions génétiques</strong> à risque d'insuffisance ovarienne précoce (ex: <strong>syndrome de Turner</strong>, mutation FMR1 prémutation).</li></ul>"},{"i":"1dc78d1b776d","n":39,"o":"39-2","u":"Définition","t":"Connaître la définition de la préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelles sont les principales indications de la préservation de la fertilité ?","a":"<p>Les principales indications de la préservation de la fertilité sont :</p><ul><li>Les <strong>indications médicales</strong> (oncofertilité ++), notamment avant un traitement potentiellement stérilisant comme la <strong>chimiothérapie gonadotoxique</strong>, la <strong>radiothérapie pelvienne</strong>, une chirurgie mutilante des gonades ou une maladie de système nécessitant un traitement gonadotoxique.</li><li>Les <strong>indications non médicales</strong> (autoconservation de ses propres gamètes), rendues possibles par la loi de 2021, hors motif médical, et prises en charge par l'assurance maladie.</li></ul>"},{"i":"5fcef25653ef","n":39,"o":"39-2","u":"Définition","t":"Connaître la définition de la préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelle est l'obligation médicale concernant la proposition de préservation de la fertilité ?","a":"<p>Tout médecin a l'<strong>obligation de proposer une préservation de la fertilité</strong> si la situation médicale l'exige, en particulier <strong>avant un traitement gonadotoxique</strong>. Ne pas proposer cette option peut constituer un préjudice pour le patient et donc une faute médicale.</p>"},{"i":"cb0bcb946195","n":39,"o":"39-2","u":"Définition","t":"Connaître la définition de la préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quels sont les publics concernés et les modalités de préservation de la fertilité masculine selon l'âge ?","a":"<p>Pour l'homme, les modalités de préservation de la fertilité selon l'âge sont :</p><ul><li><strong>Enfant prépubère</strong> : <strong>congélation de tissu testiculaire</strong> (option en oncofertilité pédiatrique, encore en développement).</li><li><strong>Adolescent pubère</strong> : <strong>autoconservation de sperme par masturbation</strong>, dès la puberté.</li><li><strong>Adulte (oncofertilité)</strong> : <strong>autoconservation de sperme</strong> (standard) ; <strong>ponction épididymaire/testiculaire</strong> si azoospermie.</li><li><strong>Adulte (hors motif médical, loi 2021)</strong> : de <strong>29 à 45 ans révolus</strong>.</li></ul>"},{"i":"e5629c0ab857","n":39,"o":"39-2","u":"Définition","t":"Connaître la définition de la préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelle est la définition de la préservation de la fertilité ?","a":"<p>La préservation de la fertilité désigne le recueil et la conservation de <strong>gamètes</strong> (spermatozoïdes, ovocytes) ou de <strong>tissus germinaux</strong> (cortex ovarien, tissu testiculaire) chez une personne.</p><p>Son objectif est de prévenir une altération prématurée de la fertilité, en vue d'une utilisation ultérieure pour l'<strong>AMP autologue</strong> ou pour <strong>restaurer la fonction germinale</strong>.</p>"},{"i":"f9f36bef6650","n":39,"o":"39-2","u":"Définition","t":"Connaître la définition de la préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quels sont les publics concernés et les modalités de préservation de la fertilité féminine selon l'âge ?","a":"<p>Pour la femme, les modalités de préservation de la fertilité selon l'âge sont :</p><ul><li><strong>Enfant prépubère</strong> : <strong>congélation de cortex ovarien</strong> (seule option).</li><li><strong>Adolescente pubère</strong> : <strong>stimulation ovarienne + vitrification ovocytaire</strong> ; la congélation de cortex ovarien est possible en cas d'urgence ou de contre-indication à la stimulation.</li><li><strong>Adulte (oncofertilité)</strong> : <strong>vitrification ovocytaire</strong>, <strong>congélation embryonnaire</strong>, <strong>cortex ovarien</strong>.</li><li><strong>Adulte (hors motif médical, loi 2021)</strong> : de <strong>29 à 37 ans révolus</strong>.</li></ul>"},{"i":"11f9431c4094","n":39,"o":"39-3","u":"Définition","t":"Connaître la définition des différentes techniques d’assistance médicale à la procréation (AMP)","q":"Dans le cadre de l'AMP, quelle est la définition de la FIV classique (fécondation in vitro) ?","a":"<p>La FIV classique est la mise en contact simple <strong>in vitro</strong> des gamètes pendant <strong>24 heures</strong>, en dehors du tractus génital féminin, où la fécondation a lieu spontanément.</p>"},{"i":"adf3ccac6c0a","n":39,"o":"39-3","u":"Définition","t":"Connaître la définition des différentes techniques d’assistance médicale à la procréation (AMP)","q":"Quelle est la définition de l'insémination artificielle (IAC ou IAD) dans le cadre de l'assistance médicale à la procréation (AMP) ?","a":"<p>L'insémination artificielle consiste à introduire de façon instrumentale les <strong>spermatozoïdes du conjoint (IAC)</strong> ou d'un <strong>donneur (IAD)</strong> dans le tractus génital féminin (intra-cervical ou intra-utérin).</p>"},{"i":"cf58e0256985","n":39,"o":"39-3","u":"Définition","t":"Connaître la définition des différentes techniques d’assistance médicale à la procréation (AMP)","q":"Qu'est-ce que la maturation in vitro (MIV) d'ovocytes en AMP, et dans quelles situations est-elle indiquée ?","a":"<p>La MIV consiste à prélever des ovocytes sur un ovaire <strong>non stimulé</strong> (ovocytes immatures) et à les faire maturer en laboratoire dans un milieu spécifique. Elle est indiquée en cas de <strong>contre-indication à la stimulation ovarienne</strong>, typiquement en présence de <strong>SOPK</strong> (risque de syndrome d'hyperstimulation ovarienne), de <strong>cancer hormonosensible</strong>, ou de chimio-thérapie urgente à instaurer.</p>"},{"i":"d48845d64d02","n":39,"o":"39-3","u":"Définition","t":"Connaître la définition des différentes techniques d’assistance médicale à la procréation (AMP)","q":"Qu'est-ce que l'ICSI (FIV avec micro-injection intracytoplasmique) en AMP, et quelle est son indication principale ?","a":"<p>L'ICSI est une technique d'AMP consistant en l'<strong>injection directe d'un seul spermatozoïde</strong> par micropipette dans le cytoplasme d'un ovocyte mature en métaphase II. Son indication principale est l'<strong>infertilité masculine sévère</strong>.</p>"},{"i":"f9d289ef0f36","n":39,"o":"39-3","u":"Définition","t":"Connaître la définition des différentes techniques d’assistance médicale à la procréation (AMP)","q":"Quelle est la définition du diagnostic génétique pré-implantatoire (DPI) en AMP, et à quels couples est-il réservé ?","a":"<p>Le DPI est une FIV pratiquée par ICSI, suivie d'un prélèvement et d'une <strong>analyse génétique</strong> (cytogénétique ou moléculaire) d'embryons aux 3<sup>e</sup> ou 5<sup>e</sup> jours. Seuls les embryons indemnes sont ensuite transférés ou congelés. Il est réservé aux couples présentant un <strong>risque de transmission d'une maladie génétique d'une particulière gravité</strong> (monogénique autosomique ou liée à l'X, récessive ou dominante).</p>"},{"i":"2c007301851b","n":39,"o":"39-4","u":"Définition","t":"Connaître la définition des différentes techniques de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelles sont les quatre techniques de préservation de la fertilité féminine décrites dans le cadre de l'oncofertilité ?","a":"<ul><li>La <strong>transposition ovarienne</strong>.</li><li>Le <strong>prélèvement d'ovocytes matures (vitrification)</strong>.</li><li>La <strong>maturation in vitro (MIV)</strong> d'ovocytes.</li><li>La <strong>conservation de tissu ovarien (cortex)</strong>.</li></ul>"},{"i":"ae2d64f9cee9","n":39,"o":"39-4","u":"Définition","t":"Connaître la définition des différentes techniques de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Qu'est-ce que l'oncofertilité dans le cadre de l'assistance médicale à la procréation (AMP) ?","a":"<p>L'oncofertilité regroupe l'ensemble des techniques visant à préserver la fertilité chez les patients, notamment avant un traitement médical potentiellement <strong>stérilisant</strong> (comme les traitements contre le cancer).</p>"},{"i":"c71e92529f1d","n":39,"o":"39-4","u":"Définition","t":"Connaître la définition des différentes techniques de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Dans quelles situations la préservation de tissu ovarien est-elle indiquée chez la femme, notamment en oncofertilité ?","a":"<ul><li>Elle est le <strong>seul moyen</strong> de préserver la fertilité chez la <strong>patiente impubère</strong>.</li><li>Elle est utilisée chez la <strong>patiente pubère en situation d'urgence</strong>, souvent associée à la maturation in vitro (MIV).</li><li>L'objectif est l'<strong>autogreffe ultérieure</strong> pour restaurer à la fois la fertilité et la fonction endocrinienne.</li></ul>"},{"i":"e9e57bdcfd38","n":39,"o":"39-4","u":"Définition","t":"Connaître la définition des différentes techniques de préservation de la fertilité féminine et masculine (enfant, adolescent, adulte)","q":"Quelles sont les techniques de préservation de la fertilité masculine disponibles ?","a":"<ul><li>L'<strong>autoconservation de sperme par masturbation</strong>, qui est la technique standard.</li><li>La <strong>ponction épididymaire ou testiculaire</strong>, indiquée en cas d'azoospermie.</li><li>L'<strong>extraction urinaire</strong>, en cas d'éjaculation rétrograde.</li><li>La <strong>congélation de tissu testiculaire</strong>, qui est une option de recherche/exception chez l'enfant prépubère avant une chimiothérapie gonadotoxique.</li></ul>"},{"i":"5dae7baa40cd","n":39,"o":"39-6","u":"Etiologies","t":"Connaître les principales étiologies d’infertilité féminine et masculine nécessitant un recours à l’AMP","q":"Quelles sont les principales étiologies masculines d'infertilité nécessitant un recours à l'AMP selon le référentiel de l'EDN ?","a":"<p>Les principales étiologies masculines d'infertilité sont :</p><ul><li><strong>Altérations spermatiques</strong> : modérées (corrigées par TMS), OATS sévère (oligo-asthéno-tératospermie), cryptozoospermie sévère, azoospermie obstructive ou non obstructive.</li><li><strong>Infertilités éjaculatoires</strong> : éjaculation rétrograde, anéjaculation.</li><li><strong>Troubles sexuels balistiques</strong>.</li><li><strong>Génétique</strong> : risque de transmission d'une maladie génétique grave.</li></ul>"},{"i":"94d26d262883","n":39,"o":"39-6","u":"Etiologies","t":"Connaître les principales étiologies d’infertilité féminine et masculine nécessitant un recours à l’AMP","q":"Quelles sont les principales étiologies de l'infertilité de couple ou idiopathique nécessitant un recours à l'AMP selon le référentiel de l'EDN ?","a":"<p>Les principales étiologies de l'infertilité de couple ou idiopathique sont :</p><ul><li><strong>Infertilité inexpliquée / idiopathique</strong> : diagnostic d'exclusion après un bilan complet du couple.</li><li><strong>Risque génétique partagé</strong> : indication potentielle de DPI.</li><li><strong>Infertilité d'origine mixte</strong> : féminine et masculine concomitantes.</li></ul>"},{"i":"c77af8fa61bb","n":39,"o":"39-6","u":"Etiologies","t":"Connaître les principales étiologies d’infertilité féminine et masculine nécessitant un recours à l’AMP","q":"Quelles sont les principales étiologies féminines d'infertilité nécessitant un recours à l'AMP selon le référentiel de l'EDN ?","a":"<p>Les principales étiologies féminines d'infertilité sont :</p><ul><li><strong>Tubaire</strong> : trompes bouchées (sans hydrosalpinx) ou absentes (post-chirurgical, post-IGH).</li><li><strong>Endométriose</strong> : avec ou sans atteinte tubaire associée.</li><li><strong>Cervical</strong> : absence de glaire ou glaire hostile aux spermatozoïdes.</li><li><strong>Ovulatoire</strong> : anovulations (ex. hypogonadisme hypogonadotrope), dysovulations (<strong>SOPK++</strong>).</li><li><strong>Ovarien</strong> : insuffisance ovarienne prématurée (<strong>IOP</strong>).</li><li><strong>Génétique</strong> : risque de transmission d'une maladie génétique grave.</li></ul>"},{"i":"27bebb05d3a3","n":39,"o":"39-7","u":"Etiologies","t":"Connaître les principales indications des inséminations artificielles","q":"Quelles sont les principales indications d'une Insémination Artificielle avec sperme de Donneur (IAD) ?","a":"<p>Les principales indications d'une IAD sont :</p><ul><li>Une <strong>femme seule</strong> (suite à la loi de 2021).</li><li>Une <strong>stérilité masculine</strong> (oligospermie extrême ou azoospermie après échec de prélèvement chirurgical de spermatozoïdes).</li><li>Un <strong>risque élevé de transmission d'une maladie génétique grave</strong> par le conjoint.</li><li>Un <strong>échec d'ICSI</strong> dans certains cas.</li></ul>"},{"i":"4e71247c9252","n":39,"o":"39-7","u":"Etiologies","t":"Connaître les principales indications des inséminations artificielles","q":"Quelles conditions techniques préalables sont requises avant de réaliser une insémination artificielle ?","a":"<p>Les conditions techniques préalables à une insémination artificielle sont :</p><ul><li>Des <strong>trompes utérines perméables</strong> (vérifiées par hystérosonographie).</li><li>La récupération d'au moins <strong>1 million de spermatozoïdes mobiles</strong> après préparation du sperme.</li><li>Un <strong>test de migration-survie positif</strong>.</li></ul>"},{"i":"9727cbf3711c","n":39,"o":"39-7","u":"Etiologies","t":"Connaître les principales indications des inséminations artificielles","q":"Quelles sont les principales indications d'une Insémination Artificielle avec sperme du Conjoint (IAC) ?","a":"<p>Les principales indications d'une IAC sont :</p><ul><li>Une <strong>infertilité d'origine cervicale</strong> (absence ou glaire hostile aux spermatozoïdes).</li><li>Des <strong>altérations spermatiques modérées</strong> (corrigées après un test de migration-survie).</li><li>Des <strong>infertilités masculines d'origine éjaculatoire</strong> ou des <strong>troubles sexuels balistiques</strong>.</li><li>Une <strong>infertilité inexpliquée / idiopathique</strong>.</li></ul>"},{"i":"1a4dcbd22b13","n":39,"o":"39-8","u":"Etiologies","t":"Connaître les principales indications de la fécondation in vitro (FIV) avec ou sans microinjection intracytoplasmique (ICSI)","q":"Quelles sont les indications de l'infertilité d'origine masculine justifiant une FIV avec ICSI ?","a":"<p>Les indications de l'infertilité d'origine masculine justifiant une FIV avec ICSI sont :</p><ul><li>L'<strong>OATS sévère</strong> (oligo-asthéno-tératospermie).</li><li>La <strong>cryptozoospermie sévère</strong>.</li><li>L'<strong>azoospermie obstructive ou non obstructive</strong>, à condition qu'un recueil positif de spermatozoïdes épididymaires ou testiculaires soit obtenu.</li></ul>"},{"i":"6f0a18a40b61","n":39,"o":"39-8","u":"Etiologies","t":"Connaître les principales indications de la fécondation in vitro (FIV) avec ou sans microinjection intracytoplasmique (ICSI)","q":"Dans quel contexte l'échec d'une fécondation lors d'une FIV classique indique-t-il une FIV avec ICSI ?","a":"<p>Un <strong>échec de fécondation après une FIV classique</strong> est une indication majeure pour recourir à une FIV avec ICSI.</p>"},{"i":"fead4dd3688c","n":39,"o":"39-8","u":"Etiologies","t":"Connaître les principales indications de la fécondation in vitro (FIV) avec ou sans microinjection intracytoplasmique (ICSI)","q":"Quelles sont les principales indications de la FIV classique pour l'assistance médicale à la procréation ?","a":"<p>Les principales indications de la FIV classique sont :</p><ul><li>L'<strong>endométriose</strong>, particulièrement avec atteinte tubaire.</li><li>L'<strong>infertilité tubaire</strong> (trompes bouchées sans hydrosalpinx ou absentes).</li><li>Les <strong>troubles de l'ovulation</strong> après échec des stimulations ovariennes simples et/ou de l'insémination artificielle.</li><li>Les <strong>échecs répétés d'insémination intra-utérine</strong>.</li><li>Les <strong>infertilités idiopathiques</strong> (inexpliquées).</li></ul>"},{"i":"4bf947697bcd","n":39,"o":"39-9","u":"Etiologies","t":"Connaître les principales indications des dons de gamètes et d’embryons","q":"Quelles sont les indications du don d'ovocytes en assistance médicale à la procréation (AMP) ?","a":"<p>Les indications du don d'ovocytes en AMP sont :</p><ul><li>Une <strong>insuffisance ovarienne prématurée (IOP)</strong>.</li><li>Un risque de transmission d’une <strong>maladie génétique d’une particulière gravité</strong> par la femme.</li><li>Des <strong>échecs de FIV ± ICSI intraconjugale</strong>, liés soit à une mauvaise réponse à la stimulation, soit à une qualité ovocytaire ou embryonnaire médiocre.</li></ul>"},{"i":"68b1037b799f","n":39,"o":"39-9","u":"Etiologies","t":"Connaître les principales indications des dons de gamètes et d’embryons","q":"Dans quels cas un couple peut-il bénéficier d'un accueil d'embryons en assistance médicale à la procréation (AMP) ?","a":"<p>L’accueil d’embryons est indiqué pour un couple présentant :</p><ul><li>Une <strong>double stérilité</strong> (masculine ET féminine), par exemple une azoospermie associée à une insuffisance ovarienne prématurée (IOP).</li><li>Une <strong>double indication génétique</strong>, c'est-à-dire une maladie génétique transmissible grave chez chaque membre du couple receveur.</li></ul>"},{"i":"dd72ee6f0d9a","n":39,"o":"39-9","u":"Etiologies","t":"Connaître les principales indications des dons de gamètes et d’embryons","q":"Quelles sont les indications de l'utilisation du don de spermatozoïdes en assistance médicale à la procréation (AMP) ?","a":"<p>Les indications du don de spermatozoïdes en AMP sont :</p><ul><li>La <strong>femme seule</strong> (loi 2021).</li><li>Une <strong>stérilité masculine sévère</strong> (oligospermie extrême ou azoospermie après échec de prélèvement chirurgical).</li><li>Un risque élevé de transmission d’une <strong>maladie génétique grave</strong> par le conjoint.</li></ul>"}]};